$dll = "G:\0.CMS-MAIN-ALL\phân tích dll\Aspose.Words.dll"

Write-Host "=== FILE INFO ==="
Get-Item -LiteralPath $dll | Select-Object FullName, Length, CreationTime, LastWriteTime | Format-List

Write-Host "=== VERSION INFO ==="
$vi = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($dll)
$vi | Select-Object FileDescription, ProductName, CompanyName, LegalCopyright, FileVersion, ProductVersion, OriginalFilename, InternalName, Language | Format-List

Write-Host "=== DIGITAL SIGNATURE ==="
try {
  $sig = Get-AuthenticodeSignature -LiteralPath $dll
  $sig | Select-Object Status, StatusMessage, SignerCertificate, TimeStamperCertificate | Format-List
  if ($sig.SignerCertificate) {
    $sig.SignerCertificate | Select-Object Subject, Issuer, NotBefore, NotAfter, Thumbprint, SerialNumber | Format-List
  }
} catch {
  Write-Host "Signature check error: $_"
}

Write-Host "=== HASHES ==="
Get-FileHash -LiteralPath $dll -Algorithm SHA256 | Format-List
Get-FileHash -LiteralPath $dll -Algorithm MD5 | Format-List

Write-Host "=== ASSEMBLY NAME ==="
try {
  [System.Reflection.AssemblyName]::GetAssemblyName($dll) | Format-List FullName, Name, Version, CultureInfo, Flags, ProcessorArchitecture
  $an = [System.Reflection.AssemblyName]::GetAssemblyName($dll)
  Write-Host ("PublicKeyToken: " + ([BitConverter]::ToString($an.GetPublicKeyToken()) -replace '-','').ToLower())
} catch {
  Write-Host "AssemblyName error: $_"
}

$dll = "G:\0.CMS-MAIN-ALL\phân tích dll\Aspose.Words.dll"

Write-Host "=== PE / .NET CHECK ==="
$bytes = [System.IO.File]::ReadAllBytes($dll)
Write-Host ("MZ: " + [char]$bytes[0] + [char]$bytes[1])
# Check for CLR header via pe
Add-Type -AssemblyName System.Reflection
try {
  $asm = [System.Reflection.Assembly]::ReflectionOnlyLoadFrom($dll)
  Write-Host "FullName:" $asm.FullName
  Write-Host "Location:" $asm.Location
  Write-Host "ImageRuntimeVersion:" $asm.ImageRuntimeVersion
  Write-Host "ExportedTypes count (may fail if refs missing):"
  try { Write-Host $asm.GetExportedTypes().Length } catch { Write-Host $_.Exception.Message }
  Write-Host "ReferencedAssemblies:"
  $asm.GetReferencedAssemblies() | ForEach-Object { $_.FullName }
} catch {
  Write-Host "ReflectionOnlyLoadFrom error: $_"
}

Write-Host "`n=== STRINGS / SUSPICIOUS INDICATORS ==="
# Scan for suspicious strings without dumping whole binary
$content = [System.IO.File]::ReadAllText($dll, [System.Text.Encoding]::ASCII)
$patterns = @(
  'cmd.exe','powershell','CreateRemoteThread','VirtualAlloc','keylog','password',
  'http://','https://','ftp://','socket','WebClient','DownloadString',
  'Aspose','License','Evaluation','Trial','www.aspose.com','products.aspose.com'
)
foreach ($p in $patterns) {
  $count = ([regex]::Matches($content, [regex]::Escape($p))).Count
  if ($count -gt 0) { Write-Host ("{0}: {1}" -f $p, $count) }
}
